INSERT INTO translations (id, table_name, record_id, field, locale, value, created_at, updated_at) VALUES ('d6707b7f-ba09-5678-b5c1-320eab2d39f3','drugs','1ab61f7c-a1e6-441a-b460-c08f55da11d6','description','fr','vit K 1,  phytoménadione solution injectable !!  dose = 1à5mg/kg : + les animaux sont petits + dose est forte; je choisis dose maxi =  0,5 ml par kg (= dose maxi...si par hasard on devait soigner lynx ou loup : taper s/ 0,2ml/kg) ; activé uniquement pour carnivores, les intoxications n\\''étant jamais accidentelles ; vu rémanence des nouveaux produits et doses nécessaires, il est impératif de prendre relais avec vitamine K1 française (50mg/comp labo TVM) en comprimés ',NOW(),NOW());
