INSERT INTO translations (id, table_name, record_id, field, locale, value, created_at, updated_at) VALUES ('19283f6c-03e0-522f-ad8f-6e6a523d9511','drugs','1ad71218-3a66-4ef0-8bb9-b2716fb59ae9','description','fr','Antibiotique ROUGE!!  ; cephalosporine de seconde génération,  actif contre gams + et certains gram-, pas actif contre pseudomonas attention ! NE PAS UTILISER CHEZ RONGEURS ! eviter chez LAGOMORPHES par voie orale en tous cas. \r\naucune donnée chez les mustélidés (ni mullineaux, ni carpenter furet, ni internet)',NOW(),NOW());
