INSERT INTO translations (id, table_name, record_id, field, locale, value, created_at, updated_at) VALUES ('4a6a9148-8664-5527-b7f2-6efc5d0a8577','drugs','21f90971-38e4-49b3-9032-fb901744d41c','description','fr','B6 et 12 pour soutien en période de mue ;  les doses renseignées sont \\" 1 goutte pour un oiseau <15 g et 2 gouttes si compris entre 15 et 45 g ; on considère qu\\''un passereau de la taille d\\''un canari consomme de 200 à 300ml d\\''eau par kg et par jour (ce qui fait entre 4et 6ml par jour pour un oiseau de 20 g) ; ça varie évidemment en fonction de l\\''humidité des aliments !!!! donc ne donner qu\\''aliments secs quand on veut que les oiseaux boivent ! \r\nconcentrer le produit à raison de 4 gouttes pour 14ml d\\''eau de boisson paraît raisonnable; ',NOW(),NOW());
