INSERT INTO translations (id, table_name, record_id, field, locale, value, created_at, updated_at) VALUES ('ceb58ac6-1e6b-5553-b429-4ac3733a7d0a','drugs','490a1a39-d04d-4e4c-bf54-466ceabe904c','description','fr','doxycycline, 20mg par comprime;  pas accessible en injectable ;\r\nantibiotique famille tetracyclines  ; mars 2025 : ne trouve plus aucune forme en solution orale ; existe poudres pour volailles, mais faut les trouver (ornicure impossible pour l\\''instant)\r\ndoses très variables et fréquence des prises aussi : vu biodisponibilité différente en fct forme galénique)...Carpenter dixit 2 prises/jr chez le Hérisson(2,5-10mg/kg 2x/jr)//et, pr rongeurs : 5mg/kg 2x/j eventuellemt associé a enroflo\r\nLagomorphes : 4mg/kg 1x par jour (on va dire 5, ça fait 1/4 comp par kg) chiens chats : 10mg,càd 1/2 comp par kg (en 1 ou 2 prises)',NOW(),NOW());
